mapper.select:
select * from `goods`

     and name like concat('%', #{name}, '%')
     and category_id = #{categoryId}
     and status = #{status}
     and status != '下架'

order by id desc

mapper.update:
update `goods` set name = #{name}, img = #{img}, price = #{price}, description = #{description},
    content = #{content}, store = #{store}, category_id = #{categoryId}, status = #{status},
    recommend = #{recommend}, views = #{views}, sale_count = #{saleCount}, `time` = #{time}
where id = #{id}
